class ContractRequest extends FormRequest{public function authorize():bool{return true;}public function rules():array{$id=$this->route('contract')?->id;return ['code'=>['required','string','max:50',Rule::unique('contracts','code')->ignore($id)],'transaction_id'=>['required','integer','exists:transactions,id',Rule::unique('contracts','transaction_id')->ignore($id)],'contract_type'=>['required',Rule::in(['sale','rental'])],'title'=>['required','string','max:255'],'contract_value'=>['required','numeric','min:0'],'deposit_amount'=>['nullable','numeric','min:0'],'signed_at'=>['nullable','date'],'start_date'=>['nullable','date'],'end_date'=>['nullable','date','after_or_equal:start_date'],'status'=>['required',Rule::in(['draft','active','completed','cancelled'])],'note'=>['nullable','string']];}}
